import{af as t,z as a,J as r,ab as o}from"./chunks/framework.C1QHhBQn.js";const s="/docs/pr/40/images/devices/general/led-battery-levels.svg",i="/docs/pr/40/images/devices/general/led-charging.svg",g=JSON.parse('{"title":"Four power LEDs","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices/capabilities/four-power-leds.md","filePath":"devices/capabilities/four-power-leds.md"}'),d={name:"devices/capabilities/four-power-leds.md"};function n(l,e,c,h,p,u){return a(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794236815000"},[...e[0]||(e[0]=[o('<h1 id="four-power-leds" tabindex="-1">Four power LEDs <a class="header-anchor" href="#four-power-leds" aria-label="Permalink to &quot;Four power LEDs&quot;">​</a></h1><p>Four power LEDs show approximate battery level and charging progress. The same indicators can also be used for startup sequences, alerts or model-specific functions. This capability describes the standard <strong>four-bar display</strong>, not every device that happens to have four visible lights.</p><h2 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Device</th><th>Implementation and limits</th></tr></thead><tbody><tr><td><a href="/docs/pr/40/devices/pro/">Pro3 / PR3</a></td><td>Four orange indicators on hardware revisions 02–04; no separate GPS/GSM diagnostic pair</td></tr><tr><td><a href="/docs/pr/40/devices/history/PR2">ProN / PR2</a></td><td>Four battery indicators, alongside two separate GPS/GSM diagnostic indicators</td></tr><tr><td><a href="/docs/pr/40/devices/zero/">Zero / ZE2</a></td><td>Four battery indicators, alongside two separate GPS/GSM diagnostic indicators</td></tr><tr><td><a href="/docs/pr/40/devices/enviro/">Enviro / EN2</a></td><td>Four battery indicators, alongside two separate GPS/GSM diagnostic indicators</td></tr><tr><td><a href="/docs/pr/40/devices/vehicle/">Vehicle / VT3</a></td><td>Four indicators also used for the <a href="/docs/pr/40/devices/vehicle/#vehicle-connection-status">vehicle connection display</a>; physical colours and orientation depend on the revision</td></tr></tbody></table><p>The ZE3 revision 01 design also has four orange indicators and the standard firmware uses this display. That design evidence does not establish which firmware is installed on a supplied ZE3; check the revision with support. ZE3 does not have the older Zero ZE2 diagnostic pair.</p><p><a href="/docs/pr/40/devices/rtk/handheld/leds">RH2 RGB status LEDs</a> use a different display and are not covered by these battery-bar thresholds. Custom products, applications and firmware can also differ.</p><h2 id="normal-battery-display" tabindex="-1">Normal battery display <a class="header-anchor" href="#normal-battery-display" aria-label="Permalink to &quot;Normal battery display&quot;">​</a></h2><p>A short status-button press normally shows the battery level briefly. The four indicators use these approximate bands:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Normal battery display</th></tr></thead><tbody><tr><td>Below 20%</td><td>First indicator flashes when showing status off charge</td></tr><tr><td>20% to below 40%</td><td>1 indicator</td></tr><tr><td>40% to below 60%</td><td>2 indicators</td></tr><tr><td>60% to below 80%</td><td>3 indicators</td></tr><tr><td>80% or more</td><td>4 indicators</td></tr></tbody></table><figure><img src="'+s+'" alt="Illustrated battery bands: below 20 percent the first indicator flashes off charge; at least 20, 40, 60 and 80 percent shows one, two, three and four indicators." tabindex="0"><figcaption>Illustrated battery bands: below 20 percent the first indicator flashes off charge; at least 20, 40, 60 and 80 percent shows one, two, three and four indicators.</figcaption></figure><p>These bands apply to the normal battery display only. Four lights are not an exact 100% reading. The diagram illustrates the pattern, not a physical case layout or a colour specification for every model.</p><h2 id="charging" tabindex="-1">Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;">​</a></h2><ul><li>Below about 95%, the highest lit battery indicator blinks, roughly one second on and one second off. At very low charge, the first indicator blinks.</li><li>At about 95% or above, the normal charging display becomes steady. This means a high charge level, not an exact 100% reading.</li><li>When unplugged and resting, the lights normally go out after any temporary status display finishes. A button press, startup or other activity can still light them.</li></ul><figure><img src="'+i+'" alt="Charging example at three bars: two steady indicators and a third that alternates on and off every second, with the fourth off. Two static frames illustrate the repeating pattern." tabindex="0"><figcaption>Charging example at three bars: two steady indicators and a third that alternates on and off every second, with the fourth off. Two static frames illustrate the repeating pattern.</figcaption></figure><p>These are battery-bar patterns, not RH2&#39;s RGB charging colours.</p><h2 id="other-uses-of-the-same-indicators" tabindex="-1">Other uses of the same indicators <a class="header-anchor" href="#other-uses-of-the-same-indicators" aria-label="Permalink to &quot;Other uses of the same indicators&quot;">​</a></h2><p>Startup, alarms, custom applications and remote LED control can temporarily replace the normal display. Some products also use the indicators for a connection or protection state: see the <a href="/docs/pr/40/devices/vehicle/#vehicle-connection-status">VT3 connection display</a> and <a href="/docs/pr/40/devices/pro/#charger-protection">Pro3 charger protection</a>.</p><p>For a practical starting point, use the <a href="/docs/pr/40/guides/leds">LED guide</a>. The number of visible indicators does not by itself establish the number of independently controllable API outputs.</p>',18)])])}const b=t(d,[["render",n]]);export{g as __pageData,b as default};
